// RF3 parcial → muestra los espacios libres y ocupados//
// RF4 parcial → al dar clic crea un ticket (pero sin fecha y hora elegida por el usuario)//
import { useEstacionamiento } from "../Context/EstacionamientoContext";

function Espacios() {
  const { espacios, crearTicket } = useEstacionamiento();

  return (
    <section>
      <h1 style={{ fontSize: 28, fontWeight: 700, color: "#0f172a", marginBottom: 8 }}>
        Asignación de Espacios
      </h1>
      <p style={{ color: "#6b7280", marginBottom: 20 }}>
        Solo haz clic en cualquier espacio libre y listo, se genera el ticket.
      </p>
      <div style={{ display: "grid", gridTemplateColumns: "repeat(5, 1fr)", gap: 10, maxWidth: 500 }}>
        {espacios.map(espacio => (
          <div
            key={espacio.id}
            onClick={() => crearTicket(espacio.id)}
            style={{
              display: "flex", flexDirection: "column", alignItems: "center",
              justifyContent: "center", padding: "16px 10px", borderRadius: 10,
              cursor: espacio.estado === "libre" ? "pointer" : "default",
              border: "2px solid",
              borderColor: espacio.estado === "libre" ? "#86efac" : "#fca5a5",
              background:   espacio.estado === "libre" ? "#dcfce7" : "#fee2e2",
              color:        espacio.estado === "libre" ? "#166534" : "#991b1b",
              gap: 4
            }}
          >
            <span style={{ fontSize: 20, fontWeight: 700 }}>{espacio.id}</span>
            <span style={{ fontSize: 11, textTransform: "uppercase", letterSpacing: 1, fontWeight: 600 }}>
              {espacio.estado === "libre" ? "Libre" : "Ocupado"}
            </span>
          </div>
        ))}
      </div>
    </section>
  );
}

export default Espacios;
